# Category edition two: each subject has an independent introduction, useful paths and reading guide.
CATEGORY_V2 = {
 'menesa-kalendars'=>{style:'paper',photo:'monthly',line:'Vieta visam, kas gaidāms.',cta:'Plānot mēnesi',facts:[['48','mēnešu pārskati'],['15','drukas dizaini'],['P–Sv','Latvijas kalendārs']],faq:[['Vai mani notikumi nonāk izdrukā?','Jā. PDF un attēls ietver izvēlētā skata redzamos notikumus un dienas piezīmes. Garākas piezīmes turpinās pielikumā.'],['Ar ko atšķiras Excel un ICS?','Excel ir rediģējama izvēlētā perioda tabula. ICS pārvieto personīgos notikumus uz citu kalendāru.'],['Kā atvērt konkrētu dienu?','Spied uz datuma. Dienas panelī vari rakstīt piezīmi vai pievienot notikumu.']]},
 'nedelas-kalendars'=>{style:'week',photo:'weekly',line:'Septiņas dienas. Tavs ritms.',cta:'Atvērt nedēļas plānu',facts:[['7','dienas vienā skatā'],['ISO','nedēļu numerācija'],['PDF','gatavs drukai']],faq:[['Kāpēc gada sākumā nedēļa var piederēt citam gadam?','ISO pirmā nedēļa ir nedēļa ar gada pirmo ceturtdienu. Tāpēc decembra beigās var sākties nākamā ISO gada pirmā nedēļa.'],['Vai nedēļas izdruka var šķērsot mēneša robežu?','Jā. Nedēļas plāns vienmēr rāda pirmdienu–svētdienu, arī tad, ja tās pieder diviem mēnešiem vai gadiem.'],['Kur pierakstīt katras dienas plānus?','Izvēlies dienu nedēļas skatā un izmanto dienas piezīmi vai pievieno notikumu ar laiku.']]},
 'gimenes-kalendars'=>{style:'family',photo:'family',line:'Kopīgs skats uz jūsu nedēļu.',cta:'Sākt ģimenes plānu',facts:[['8','ģimenes locekļi'],['7','dienu ēdienkarte'],['15','drukas dizaini']],faq:[['Vai kalendārs sinhronizējas ģimenes telefonos?','Ieraksti glabājas šajā pārlūkā. Pārvietošanai izmanto JSON dublējumu; ICS fails paredzēts notikumu importam citā kalendārā.'],['Kā izveidot pirkumu sarakstu?','Maltītei pievieno sastāvdaļas, atdalot tās ar komatiem. Produktus vari pievienot un atzīmēt arī atsevišķi.'],['Vai atkārtojumu var ierobežot?','Jā. Nedēļas notikumam norādi atkārtojuma pēdējo dienu. Bez tās notikums turpinās katru nedēļu.']]},
 'atvalinajuma-planotajs'=>{style:'escape',photo:'jurmala',line:'Vairāk laika atpūtai Latvijā.',cta:'Aprēķināt savu atvaļinājumu',facts:[['2027–2030','plānošanas gadi'],['Tavs','dienu budžets'],['LV','svētku datumi']],faq:[['Vai ieteikums jau ir apstiprināts atvaļinājums?','Nē. Tas ir aprēķins pēc izvēlētā darba grafika un svētku brīvdienām. Datumi jāsaskaņo ar darba devēju.'],['Vai sešu dienu darba nedēļa dod citu rezultātu?','Jā. Atvaļinājuma darba dienas tiek skaitītas pēc izvēlētā grafika. Papildu brīvās vai darba dienas ievadi iestatījumos.'],['Vai kopējā plānā dienas var ieskaitīt divreiz?','Izvēlētie periodi nedrīkst pārklāties. Mainot darba nedēļu vai īpašos datumus, saglabāto periodu izmaksas pārrēķinās. Citu gadu ieraksti paliek saglabāti.'],['Kuru kalendāra failu izvēlēties?','Atvaļinājuma darba dienu ICS failā ir tikai tās dienas, kurās pēc tava grafika būtu jāstrādā. Atpūtas periodu ICS failā ir viss intervāls, ieskaitot brīvās dienas. CSV ir gada plāna tabula.'],['Kā plānot atpūtu gadu mijā?','Katram gadam ir savs budžets. Periodu sadali 31. decembrī un 1. janvārī un saglabā abas daļas attiecīgajos gados.']]},
 'mainu-grafiks'=>{style:'shift',photo:'clock',line:'Diena. Nakts. Brīvs.',cta:'Veidot maiņu ciklu',facts:[['31','diena ciklā'],['D / N','dienas un nakts maiņas'],['15','drukas dizaini']],faq:[['Kurā datumā ieskaita nakts maiņu?','Maiņa pieder tās sākuma datumam. Ja beigu laiks nav vēlāk par sākuma laiku, beigas ir nākamajā dienā.'],['Vai konkrētu datumu var mainīt, nepārrakstot ciklu?','Jā. Atlasot dienu, saglabā izņēmumu. Poga «Atjaunot ciklu» atceļ tikai šīs dienas labojumu.'],['Vai darba stundās ieskaita pārtraukumu?','No maiņas ilguma atņem norādīto pārtraukumu. Šis ir personīgs grafiks; darba un atpūtas laika prasības pārbaudi atsevišķi.']]},
 'varda-dienas'=>{style:'names',photo:'flowers',line:'Mazs datums. Liels prieks.',cta:'Atrast vārda dienu',facts:[['1 032','tradicionālie ieraksti'],['4 620','papildu ieraksti'],['VVC','oficiālais avots']],faq:[['Vai Jānis un Janis ir viens ieraksts?','Nē. Saglabājam VVC avota rakstību. Meklēšana bez garumzīmēm palīdz atrast abus, bet datumi un saraksta veids paliek atsevišķi.'],['Ko nozīmē paplašinātais saraksts?','Tas ietver papildu kalendārvārdus. Tradicionālais un paplašinātais saraksts ir skaidri atzīmēts katrā rezultātā.'],['Vai var saglabāt atlasīto vārdu datumus?','Jā. Izvēlies gadu un filtrus, tad lejupielādē atlasīto datumu ICS failu.']]},
 'svetki-un-tradicijas'=>{style:'stories',photo:'ligo',line:'Latvijas gads dzīvos stāstos.',cta:'Iepazīt datumus un tradīcijas',facts:[['Latvija','gadskārtas un tradīcijas'],['Atsevišķi','brīvdienu statuss'],['Avoti','pie katras tēmas']],faq:[['Vai visas šīs dienas ir brīvdienas?','Nē. Svētku brīvdienas, atceres dienas, atzīmējamās dienas un kultūras tradīcijas ir dažādas kategorijas. Izmanto veida filtru.'],['Kāpēc Meteņiem nav viena datuma visiem gadiem?','Avoti un novadu tradīcijas atšķiras. Konkrētu pasākumu datumus izziņo rīkotāji; tos nepārceļam no iepriekšējiem gadiem.'],['Vai lejupielādē ietilpst visi tēmas datumi?','ICS failā ietilpst tikai izvēlētajam gadam un mēnesim atbilstošie, pārbaudāmie datumi.']]},
 'skolas-brivlaiki'=>{style:'school',photo:'school',line:'Mācību gads ar skaidriem datumiem.',cta:'Skatīt skolu brīvlaikus',facts:[['1.–12.','klašu datumi'],['11','valsts augstskolas'],['MK 768','publicētais skolu grafiks']],faq:[['Vai skolu un augstskolu brīvdienas sakrīt?','Augstskolas publicē patstāvīgus akadēmiskos kalendārus. To studiju un eksāmenu periodi tiek rādīti atsevišķi no brīvlaikiem.'],['Kāpēc nākamā mācību gada datumi var nebūt redzami?','Ja nav publicēts oficiāls grafiks, iepriekšējā gada datumus nepārceļam. Avota statuss ir norādīts pie gada.'],['Vai var izvēlēties savu klasi?','Jā. Izlaiduma klašu mācību gada beigas atšķiras; 1. klases papildu brīvdienu nedēļu nosaka pati skola.']]},
 'stundu-saraksts'=>{style:'timetable',photo:'ring-planner',line:'Vairāk skaidrības katrai mācību dienai.',cta:'Veidot savu stundu sarakstu',facts:[['7','nedēļas dienas'],['15','drukas dizaini'],['Pārbaude','stundu pārklāšanās']],faq:[['Vai stundas tiek atkārtotas automātiski?','Jā, izvēlētajā nedēļas dienā no perioda sākuma līdz beigām. Skolas brīvlaiks netiek izslēgts automātiski.'],['Kā tiek pārbaudīta pārklāšanās?','Salīdzina stundas laiku un faktiskos kopīgos datumus norādītajos mācību periodos. Stundas ar kopīgu robežlaiku nepārklājas.'],['Vai izdrukā būs arī skolotājs un telpa?','Jā. Ja šie lauki aizpildīti, tie tiek iekļauti nedēļas PDF un attēlā kopā ar stundas laiku un priekšmetu.']]},
 'visi-riki'=>{style:'directory',photo:'desk-tools',line:'Aprēķini dienas un izveido savu kalendāru.',cta:'Atrast piemērotu rīku',facts:[['24','kalendāri un rīki'],['5','sadaļas pēc uzdevuma'],['Bez konta','vari sākt uzreiz']],faq:[['Ar kuru rīku aprēķināt dienas?','Datumu kalkulators palīdz atrast dienu starpību vai jaunu datumu. Darba dienu kalendārā vari ņemt vērā darba grafiku un Latvijas svētku brīvdienas. Ja vajadzīgs pārskatāms plāns, atver mēneša vai nedēļas kalendāru.'],['Kā saglabāt biežāk lietotos rīkus?','Nospied grāmatzīmi rīka kartītē. Pēc tam ieslēdz filtru «Saglabātie rīki», lai redzētu savu izlasi. Izvēle paliek šajā pārlūkā arī pēc lapas aizvēršanas.'],['Kur glabājas mani personīgie plāni?','Personīgie notikumi un plānotāju ieraksti glabājas tavā pārlūkā. Tie netiek automātiski sinhronizēti citās ierīcēs. Ja rīks piedāvā datu dublējumu, saglabā to pirms pārlūka datu dzēšanas vai ierīces maiņas.']]},
 'saullekts-saulriets'=>{style:'sun',photo:'summer',line:'Seko gaismai savā pilsētā.',cta:'Izpētīt Saules ceļu',facts:[['82','Latvijas pilsētas'],['Europe/Riga','vietējais laiks'],['Gada līkne','dienas garuma salīdzinājums']],faq:[['Vai laiks mainās, izvēloties citu pilsētu?','Jā. Saullēkts, saulriets un krēsla ir atkarīgi no koordinātām. Laika josla visā Latvijā ir viena.'],['Kāpēc aiz loga Saule pazūd citā laikā?','Aprēķins izmanto standarta horizontu. Ēkas, mežs, reljefs un atmosfēras apstākļi var mainīt faktisko redzamību.'],['Ko rāda gada līkne?','Katra mēneša 21. datuma dienas garumu izvēlētajā pilsētā. Tā palīdz salīdzināt gadalaikus, nevis prognozē laikapstākļus.']]},
 'meness-kalendars'=>{style:'lunar',photo:'moon',line:'Tuvāk Mēnesim. Dienu pēc dienas.',cta:'Izvēlēties Mēness mēnesi',facts:[['48','mēneši 2027–2030'],['12.00','dienas attēlojuma laiks Latvijā'],['4','veidnes katram periodam']],faq:[['Vai redzamais Mēness ir nākotnes fotogrāfija?','Nē. Dienas attēls ir aprēķināta ilustrācija ar īstu NASA LRO virsmas karti. Gadu vākiem izmantotas arhīva misiju fotogrāfijas.'],['Vai kalendārs paredzēts visai Latvijai?','Jā. Šis ir ģeocentrisks fāžu pārskats pēc Latvijas laika. Vietējais Mēness lēkts un riets ir atsevišķā pilsētu rīkā.'],['Kā apskatīt konkrētu dienu?','Atver mēneša lapu un spied uz datuma. Atlasītās dienas panelī redzams palielināts disks un apgaismojums.']]},
 'meness-fazes'=>{style:'phases',photo:'moon',line:'Četri precīzi mirkļi katrā ciklā.',cta:'Atrast fāzes datumu',facts:[['USNO','galveno fāžu brīži'],['4','fāžu veidi'],['UTC + LV','pārbaudāmi laiki']],faq:[['Vai pilnmēness ilgst visu dienu?','Astronomiskais pilnmēness ir noteikts brīdis. Acīm disks var izskatīties gandrīz pilns arī blakus naktīs.'],['Kāpēc pie laika redzams arī UTC?','UTC ir avota laiks. Latvijas pulksteņa laiks pārrēķināts Europe/Riga joslā, ievērojot vasaras un ziemas laiku.'],['Vai fāzes brīdis atkarīgs no pilsētas?','Galvenās fāzes brīdis ir kopīgs visai pasaulei. Vietējais Mēness augstums, lēkts un riets gan atšķiras.']]},
 'gadalaiki'=>{style:'seasons',photo:'autumn',line:'Četras sezonas. Viena Latvija.',cta:'Apskatīt gadalaiku sākumu',facts:[['4','astronomiskie sākumi'],['3','gadalaiku iedalījumi'],['2027–2030','Aprēķinu gadi']],faq:[['Vai astronomiskais pavasaris vienmēr sākas 21. martā?','Nē. Ekvinokcijas brīdis katru gadu tiek aprēķināts atsevišķi un pārrēķināts Latvijas laikā.'],['Ar ko atšķiras kalendārais un astronomiskais gadalaiks?','Kalendārais iedalījums sākas mēneša pirmajā datumā; astronomiskais — ekvinokcijas vai saulgriežu brīdī.'],['Vai meteoroloģiskajai ziemai ir fiksēts sākuma datums?','Nē. Latvijas temperatūras gadalaiki atkarīgi no faktiskās vidējās gaisa temperatūras gaitas.']]},
 'astronomiskais-kalendars'=>{style:'cosmos',photo:'earth',line:'Latvijas debesis vienā kalendārā.',cta:'Plānot novērošanas vakaru',facts:[['82','pilsētu redzamība'],['5','notikumu grupas'],['ICS','debesu notikumu plāns']],faq:[['Vai katrs saraksta aptumsums būs redzams Latvijā?','Nē. Pie aptumsuma atsevišķi norādīts aprēķins izvēlētajai pilsētai. Globālais notikums un vietējā redzamība ir dažādas lietas.'],['Ko nozīmē Perseīdu novērošanas logs?','Tas ir tumšās nakts plānošanas periods izvēlētajā pilsētā. Tas negarantē meteoru skaitu, maksimumu vai skaidru laiku.'],['Vai ICS fails atjaunojas pats?','Nē. Tas ir izvēlēto notikumu eksports vienā brīdī. Ja maini pilsētu, gadu vai filtrus, saglabā jaunu failu.']]}
}.freeze

def v2_photo(id,klass='',alt='')
 mapped={'monthly'=>'calendar','weekly'=>'week','ring-planner'=>'planner','desk-tools'=>'alltools','clock'=>'shift','flowers'=>'names','family'=>'family','ligo'=>'culture','school'=>'school','summer'=>'sunrise','winter'=>'moon','autumn'=>'seasons','jurmala'=>'vacation','independence'=>'names'}.fetch(id,id)
 %(<img class="#{klass} v2-illustration" src="/assets/category-vector/#{mapped}.svg?v={{ site.data.build.asset_version }}" alt="#{h(alt)}" width="640" height="520" decoding="#{klass.include?('v2-scene-photo') ? 'sync' : 'async'}"#{klass.include?('v2-scene-photo') ? ' loading="eager" fetchpriority="high"' : ''}>)
end

def v2_calendar_scene(week=false)
 first=Date.new(2027,1,1)
 if week
  start=Date.commercial(2027,1,1)
  days=(0..6).map{|i|d=start+i;%(<a href="/nedelas-kalendars/?date=#{d}&amp;view=week"><small>#{DAYS[i]}</small><b>#{d.day}</b><span class="v2-week-line"></span><span class="v2-week-line short"></span></a>)}.join
  %(<div class="v2-paper v2-week-paper"><span class="v2-paper-kicker">NEDĒĻAS PLĀNS · 2027</span><strong>4.–10. janvāris</strong><div class="v2-week-preview">#{days}</div><span class="v2-paper-foot">ISO 01 <span>PIRMDIENA–SVĒTDIENA</span></span></div>)
 else
  cells=Array.new(first.cwday-1,'<span></span>')+(1..31).map{|d|date=Date.new(2027,1,d);%(<a #{date.cwday>5||d==1 ? 'class="off"' : ''} href="/menesa-kalendars/?date=#{date}&amp;view=month" aria-label="#{d}. janvāris 2027">#{d}</a>)}
  %(<div class="v2-paper v2-month-paper"><span class="v2-paper-kicker">TAVS GADS, TAVI PLĀNI</span><strong>Janvāris <em>2027</em></strong><div class="v2-mini-calendar">#{DAYS.map{|d|"<small>#{d}</small>"}.join}#{cells.join}</div><span class="v2-paper-foot">KALENDĀRS365 <span>LATVIJA</span></span></div>)
 end
end

def category_v2_scene(slug,cfg)
 case slug
 when 'menesa-kalendars','nedelas-kalendars'
  v2_photo(cfg[:photo],'v2-scene-backdrop')+v2_calendar_scene(slug=='nedelas-kalendars')
 when 'gimenes-kalendars'
  v2_photo('family','v2-scene-photo')+'<div class="v2-floating-note"><span class="v2-paper-kicker">JŪSU KOPĪGAIS PLĀNS</span><strong>Katram sava krāsa.</strong><div class="v2-people-colors"><i></i><i></i><i></i><i></i><i></i></div><span>Notikumi · maltītes · pirkumi</span></div>'
 when 'stundu-saraksts'
  v2_photo('ring-planner','v2-scene-photo')+'<div class="v2-floating-note"><span class="v2-paper-kicker">MĀCĪBU NEDĒĻA</span><strong>Priekšmets. Telpa. Laiks.</strong><div class="v2-subject-bars"><i></i><i></i><i></i></div><span>Pielāgo sarakstu savām mācībām.</span></div>'
 when 'mainu-grafiks'
  v2_photo('clock','v2-scene-backdrop')+'<div class="v2-shift-wheel"><span class="v2-paper-kicker">IZVĒLIES SAVU RITMU</span><strong>D / N / B / B</strong><div><span>Diena</span><span>Nakts</span><span>Brīvs</span><span>Brīvs</span></div><p>Maiņu secības piemērs</p></div>'
 when 'varda-dienas'
  v2_photo('flowers','v2-scene-photo')+'<div class="v2-name-letter"><span class="v2-paper-kicker">VĀRDA DIENAS LATVIJĀ</span><strong>Atceries<br>savējos.</strong><a href="#category-workspace">Atrast vārdu <span>↗</span></a></div>'
 when 'meness-kalendars'
  photo = lunar_cover(2027)
  %(<figure class="v2-lunar-photograph"><img src="#{h(photo.fetch('src'))}?v={{ site.data.build.asset_version }}" alt="#{h(photo.fetch('alt'))}" width="#{photo.fetch('width')}" height="#{photo.fetch('height')}" fetchpriority="high" decoding="async"><figcaption>#{h(photo.fetch('credit'))} · 19.12.1972. </figcaption></figure>)
 when 'meness-fazes'
  '<div class="v2-phase-arc">'+%w[new first full last].each_with_index.map{|phase,i|%(<div><img src="/assets/category-vector/phase-#{phase}.svg" alt="" width="160" height="160"><small>#{['Jaunmēness','Pirmais ceturksnis','Pilnmēness','Pēdējais ceturksnis'][i]}</small></div>)}.join+'</div><span class="v2-mission-label">Mēness cikls · ilustratīvs zīmējums</span>'
 when 'astronomiskais-kalendars'
  '<img class="v2-astronomy-observatory" src="/assets/astronomy-events/observatory.svg" width="400" height="400" alt="Teleskops zem zvaigžņotām debesīm"><span class="v2-mission-label">Tavs ceļvedis debess notikumos</span>'
 when 'gadalaiki'
  names=%w[Pavasaris Vasara Rudens Ziema]
  cases=%w[pavasara vasaras rudens ziemas]
  '<div class="season-hero-gallery">'+%w[spring summer autumn winter].each_with_index.map{|season,i|%(<a class="season-hero-tile season-hero-tile--#{season}" href="#season-#{season}"><img src="/assets/season-scenes/#{season}.svg?v={{ site.data.build.asset_version }}" alt="" width="600" height="500" decoding="async"><span>#{names[i]}<b aria-hidden="true">↗</b></span></a>)}.join+'</div>'
 when 'saullekts-saulriets'
  v2_photo('summer','v2-scene-photo')+'<div class="v2-solar-arc" aria-hidden="true"><svg viewBox="0 0 500 260"><defs><linearGradient id="v2-sun-g"><stop stop-color="#ffe9ae"/><stop offset="1" stop-color="#d69b4f"/></linearGradient></defs><path d="M40 210Q250 -130 460 210" fill="none" stroke="#fff4d7" stroke-width="2" stroke-dasharray="4 7"/><path d="M35 211H465" stroke="#fff4d7" stroke-width="1"/><circle cx="250" cy="40" r="20" fill="url(#v2-sun-g)"/></svg></div><span class="v2-mission-label">Saules ceļš · ilustratīvs zīmējums</span>'
 when 'skolas-brivlaiki'
  v2_photo('school','v2-scene-photo')+'<a class="v2-floating-note" href="#augstskolas"><span class="v2-paper-kicker">SKOLAS UN AUGSTSKOLAS</span><strong>Katram savs kalendārs.</strong><span>Klases · brīvlaiki · studiju periodi ↗</span></a>'
 when 'visi-riki'
  tools_directory_scene
 when 'svetki-un-tradicijas'
  photo=tradition_cover(OCCASIONS.find{|item|item['slug']=='ligo-diena'}.fetch('photo'))
  %(<figure class="v2-tradition-hero-photo"><img src="#{h(photo.fetch('src'))}" srcset="#{h(photo.fetch('srcset'))}" sizes="(max-width: 900px) 90vw, 46vw" width="#{photo.fetch('width')}" height="#{photo.fetch('height')}" alt="#{h(photo.fetch('alt'))}" decoding="async" fetchpriority="high"><figcaption><strong>No Jāņiem līdz Ziemassvētkiem.</strong>#{h(photo.fetch('caption'))}</figcaption></figure>)
 else
  v2_photo(cfg[:photo],'v2-scene-photo')+'<div class="v2-story-tag"><span>LAIKS SEV</span><strong>Vairāk brīvu dienu.</strong></div>'
 end
end

def category_hero_markup(slug,heading)
 cfg=CATEGORY_V2.fetch(slug);info=CATEGORY_EXPERIENCES.fetch(slug);links=info[4..-1].map{|l|l.split('|',2)}
 if %w[menesa-kalendars nedelas-kalendars gimenes-kalendars stundu-saraksts mainu-grafiks].include?(slug)
  existing=links.find{|label,url|label=='Drukas dizaini'}
  if existing;existing[1]='#v2-designs';else links << ['Drukas dizaini','#v2-designs'];end
 end
 nav=links.each_with_index.map{|(label,url),i|%(<a href="#{url}"><span>#{format('%02d',i+1)}</span>#{h(label)}<b aria-hidden="true">↗</b></a>)}.join
 %(<header class="v2-hero v2-hero--#{cfg[:style]}"><div class="v2-hero-copy"><span class="eyebrow">#{h(info[1])}</span><h1>#{h(heading)}</h1><p class="v2-hero-line">#{h(cfg[:line])}</p><p class="v2-hero-description">#{h(info[3])}</p><a class="v2-primary" href="#{links.first.last}">#{h(cfg[:cta])}<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12h14m-6-6 6 6-6 6"/></svg></a></div><div class="v2-hero-scene">#{category_v2_scene(slug,cfg)}</div><div class="v2-hero-facts">#{cfg[:facts].map{|value,label|"<div><strong>#{h(value)}</strong><span>#{h(label.sub(/\A\p{Ll}/){|first|first.upcase})}</span></div>"}.join}</div></header><nav class="v2-section-nav" aria-label="Šīs lapas sadaļas">#{nav}<a href="#v2-answers"><span>?</span>Jautājumi un atbildes<b aria-hidden="true">↓</b></a></nav>)
end

def category_v2_finish(slug,body)
 # Preserve the working data attributes; rebuild the ordering and surrounding information.
 if %w[gimenes-kalendars stundu-saraksts].include?(slug)
  body=body.sub(/<header class="organizer-hero.*?<\/header>/m,'')
  week=body[/<section class="organizer-card organizer-week-card">.*?<\/section>/m]
  if week
   body=body.sub(week,'');body=body.sub(/(<\/section>)/, '\\1'+week)
  end
 end
 guide=body[/<section class="category-guide" id="category-guide">.*?<\/section>/m]
 body=body.sub(guide,'') if guide
 if %w[menesa-kalendars nedelas-kalendars gimenes-kalendars stundu-saraksts mainu-grafiks].include?(slug)
  kind=%w[menesa-kalendars nedelas-kalendars].include?(slug) ? 'period' : {'gimenes-kalendars'=>'family','stundu-saraksts'=>'school','mainu-grafiks'=>'shift'}[slug]
  body+=%(<section class="v2-design-studio" id="v2-designs" data-v2-designs="#{kind}"><div class="v2-block-heading"><div><span class="eyebrow">TAVS PLĀNS UZ PAPĪRA</span><h2>15 veidi, kā izskatās tavs kalendārs.</h2><p>Izvēlies noformējumu. Priekšskatījums izmanto tavus atlasītos datumus un ierakstus.</p></div><span class="v2-format-tag">A4 · 600 ppi</span></div><div class="v2-design-grid" data-v2-design-grid></div><p data-v2-design-status role="status"></p><dialog class="v2-preview-dialog" data-v2-preview aria-label="Kalendāra priekšskatījums"><div class="v2-preview-bar"><strong data-v2-preview-title></strong><button type="button" data-v2-preview-close aria-label="Aizvērt priekšskatījumu">×</button></div><div data-v2-preview-content></div><div class="v2-preview-downloads"><button type="button" data-v2-download="pdf"><img src="/assets/file-pdf.svg" width="24" height="24" alt="">PDF ↓</button><button type="button" data-v2-download="webp"><img src="/assets/file-image.svg" width="24" height="24" alt="">Attēls ↓</button><span data-v2-preview-status role="status"></span></div></dialog></section>)
  if slug=='nedelas-kalendars'
   body=body.sub('class="v2-design-studio"','class="v2-design-studio weekly-design-studio"')
   body=body.sub('15 veidi, kā izskatās tavs kalendārs.','15 nedēļas plānotāji drukai')
   body=body.sub('Izvēlies noformējumu. Priekšskatījums izmanto tavus atlasītos datumus un ierakstus.','Izvēlies dienu slejas, kartītes vai horizontālu plānu. Priekšskatījumā un lejupielādē būs tava atlasītā nedēļa, notikumi un piezīmes.')
   body=body.sub('A4 · 600 ppi','PDF · Attēls · A4')
   if File.file?('downloads/nedelas/manifest.json')
    tiles=JSON.parse(File.read('downloads/nedelas/manifest.json')).fetch('items').map do |item|
     %(<button class="v2-design-tile" type="button" data-v2-design="#{item['design']}"><span aria-hidden="true"><img src="#{item['preview']}" width="900" height="636" loading="lazy" decoding="async" alt=""></span><strong>#{format('%02d',item['design'])} · #{h(item['title'])}</strong><small>#{h(item['description'])}</small><span class="v2-tile-action">Atvērt priekšskatījumu <b aria-hidden="true">↗</b></span></button>)
    end.join
    body=body.sub('<div class="v2-design-grid" data-v2-design-grid></div>',%(<div class="v2-design-grid" data-v2-design-grid>#{tiles}</div>))
   end
   body+=%(<section class="weekly-print-guide" aria-labelledby="weekly-print-guide-title"><div><span class="eyebrow">SAVA NEDĒĻA. SAVS RITMS.</span><h2 id="weekly-print-guide-title">No plāna ekrānā līdz plānam uz galda</h2></div><div><p>Atvēli vietu gan darbiem, gan atpūtai. Nedēļas kalendārā vari salikt līdzās tikšanās, mācības, ģimenes notikumus un savus uzdevumus. Izvēlies vajadzīgo datumu un dienai pievieno notikumu vai piezīmi; drukas priekšskatījumā redzēsi savus ierakstus kopā ar visu nedēļu no pirmdienas līdz svētdienai.</p><p>Dienu slejas der ātram nedēļas pārskatam, kartītes dod katrai dienai atsevišķu vietu, bet horizontālajos plānos ir vairāk vietas pierakstiem. Rīgas siluets, Baltijas krasts, mežs un Latvju raksti piešķir katram noformējumam savu noskaņu. Visos 15 dizainos ir Kalendārs365 zīmola paraksts un vietnes adrese.</p><p>Atver izvēlēto dizainu un saglabā <strong>PDF</strong> vai <strong>Attēls</strong> failu. PDF ir A4 horizontālā formātā ar asu vektoru tekstu, bet pilnais attēls ir 7016 × 4961 pikseļi jeb 600 ppi A4 izmērā. Garām piezīmēm automātiski pievienojas pielikums, lai teksts nepazustu. Drukājot izvēlies A4 horizontāli un pārbaudi priekšskatījumu; plašākam periodam atver <a href="/menesa-kalendars/">mēneša kalendāru</a>, bet savam noformējumam izmanto <a href="/izveidot-kalendaru/">kalendāra veidotāju</a>.</p></div></section>)
  elsif slug=='gimenes-kalendars'
   body=body.sub('class="v2-design-studio"','class="v2-design-studio weekly-design-studio family-design-studio"')
   body=body.sub('15 veidi, kā izskatās tavs kalendārs.','15 ģimenes plānotāji drukai')
   body=body.sub('Izvēlies noformējumu. Priekšskatījums izmanto tavus atlasītos datumus un ierakstus.','Katra cilvēka plāni, kopīgās lietas un maltītes vienā pārskatā. Atver dizainu, lai redzētu savu izvēlēto nedēļu un saglabātu to drukai.')
   body=body.sub('A4 · 600 ppi','PDF · Attēls · A4')
   if File.file?('downloads/gimenes/manifest.json')
    tiles=JSON.parse(File.read('downloads/gimenes/manifest.json')).fetch('items').map do |item|
     %(<button class="v2-design-tile" type="button" data-v2-design="#{item['design']}"><span aria-hidden="true"><img src="#{item['preview']}" width="900" height="636" loading="lazy" decoding="async" alt=""></span><strong>#{format('%02d',item['design'])} · #{h(item['title'])}</strong><small>#{h(item['description'])}</small><span class="v2-tile-action">Atvērt priekšskatījumu <b aria-hidden="true">↗</b></span></button>)
    end.join
    body=body.sub('<div class="v2-design-grid" data-v2-design-grid></div>',%(<div class="v2-design-grid" data-v2-design-grid>#{tiles}</div>))
   end
   body+=%(<section class="weekly-print-guide family-print-guide" aria-labelledby="family-print-guide-title"><div><span class="eyebrow">KATRAM SAVA VIETA. VISIEM VIENS PLĀNS.</span><h2 id="family-print-guide-title">Nedēļa, kuru redz visa ģimene</h2></div><div><p>Skola, darbs, pulciņi un kopīgs brīvais laiks ir vieglāk pārskatāmi vienā kalendārā. Pievieno ģimenes locekļus, katram izvēlies krāsu un norādi, kurš atbild par konkrēto notikumu vai mājas darbu. Kopīgās lietas vari atstāt bez viena atbildīgā. Nedēļas izdrukā saglabājas vārdi, laika intervāli un paveikto darbu atzīmes; regulārie ieraksti parādās tikai savā atkārtošanās periodā.</p><p>Izvēlies no 15 oriģināliem noformējumiem. Katra cilvēka slejas palīdz salīdzināt grafikus, dienu kartītes atvēl vairāk vietas vienai dienai, bet ajanda rāda notikumus secīgās rindās. Ēdienkartes izkārtojumos maltīte ir blakus tās dienas plāniem. Pirkumu saraksts tiek iekļauts izdrukā kopā ar daudzumiem un atzīmēm par nopirkto; tas ir kopīgs saraksts, nevis tikai vienas nedēļas produkti. Arī garš saraksts vai pilna diena nepazūd: turpinājums nonāk pielikumā.</p><p>Atver priekšskatījumu un saglabā <strong>PDF</strong> vai <strong>Attēls</strong> failu ar Kalendārs365 zīmola parakstu. PDF ir A4 horizontālā formātā ar vektoru tekstu; attēls ir 7016 × 4961 pikseļi jeb 600 ppi A4 izmērā. Plānotājs nesinhronizē ierakstus citos tālruņos, tāpēc pārcelšanai izmanto JSON dublējumu, bet notikumiem citā kalendāra lietotnē — ICS eksportu. Salīdzini arī <a href="/skolas-brivlaiki/">skolu brīvlaikus</a> un savu <a href="/atvalinajuma-planotajs/">atvaļinājuma plānu</a>, lai kopīgais laiks būtu ieplānots laikus.</p></div></section>)
  elsif slug=='stundu-saraksts'
   body=body.sub('class="v2-design-studio"','class="v2-design-studio weekly-design-studio school-design-studio"')
   body=body.sub('15 veidi, kā izskatās tavs kalendārs.','15 stundu saraksti drukai')
   body=body.sub('Izvēlies noformējumu. Priekšskatījums izmanto tavus atlasītos datumus un ierakstus.','Izvēlies mācību dienu slejas, kartītes vai ajandu. Priekšskatījumā būs tava izvēlētā nedēļa, stundas, telpas, skolotāji un uzdevumi.')
   body=body.sub('A4 · 600 ppi','PDF · Attēls · A4')
   if File.file?('downloads/stundas/manifest.json')
    tiles=JSON.parse(File.read('downloads/stundas/manifest.json')).fetch('items').map do |item|
     %(<button class="v2-design-tile" type="button" data-v2-design="#{item['design']}"><span aria-hidden="true"><img src="#{item['preview']}" width="900" height="636" loading="lazy" decoding="async" alt=""></span><strong>#{format('%02d',item['design'])} · #{h(item['title'])}</strong><small>#{h(item['description'])}</small><span class="v2-tile-action">Atvērt priekšskatījumu <b aria-hidden="true">↗</b></span></button>)
    end.join
    body=body.sub('<div class="v2-design-grid" data-v2-design-grid></div>',%(<div class="v2-design-grid" data-v2-design-grid>#{tiles}</div>))
   end
   body+=%(<section class="weekly-print-guide school-print-guide" aria-labelledby="school-print-guide-title"><div><span class="eyebrow">MĀCĪBĀM SAVS RITMS</span><h2 id="school-print-guide-title">Pārskatāma nedēļa uz galda vai somā</h2></div><div><p>Izvēlies nedēļu un pievieno nodarbības ar sākuma un beigu laiku. Norādi telpu, skolotāju un periodu, kurā stunda atkārtojas. Saraksts der gan skolas stundām, gan pulciņiem un studiju nodarbībām. Tajā ir vieta arī sestdienai un svētdienai. Pirms saglabāšanas plānotājs pārbauda, vai divām stundām norādītajā periodā nav kopīga laika.</p><p>Katram no 15 dizainiem ir savs izkārtojums un ilustrācija. Karmīna akadēmijas slejas palīdz salīdzināt darba dienas, dienu kartītes nodala katras dienas plānus, bet ajanda atstāj atsevišķu vietu uzdevumiem. Literata virsraksti un DM Sans ieraksti veido skaidru lasīšanas secību. Izdrukā redzēsi izvēlētās nedēļas stundas un termiņus, arī paveiktos uzdevumus ar atbilstošu atzīmi. Ja ierakstu ir daudz, pilns turpinājums nonāk pielikumā.</p><p>Atver priekšskatījumu un saglabā <strong>PDF</strong> ar vektoru tekstu vai <strong>Attēls</strong> failu 7016 × 4961 pikseļu izmērā. Tas atbilst 600 ppi A4 horizontālai lapai. Katrā lapā ir Kalendārs365 zīmola paraksts un kalendars365.lv adrese. Vairāku lapu attēlus saņemsi ZIP failā. Drukāšanai izvēlies A4 horizontāli un izslēdz pārlūka galveni un kājeni. Mācību brīvdienas pārbaudi <a href="/skolas-brivlaiki/">skolu brīvlaiku pārskatā</a>, bet augstskolas termiņus meklē <a href="/studiju-kalendars/">studiju kalendāros</a>. Savu sarakstu vari pārcelt ar JSON dublējumu vai eksportēt nodarbības ICS formātā.</p></div></section>)
  elsif slug=='mainu-grafiks'
   body=body.sub('class="v2-design-studio"','class="v2-design-studio weekly-design-studio shift-design-studio"')
   body=body.sub('15 veidi, kā izskatās tavs kalendārs.','15 maiņu grafika dizaini drukai')
   body=body.sub('Izvēlies noformējumu. Priekšskatījums izmanto tavus atlasītos datumus un ierakstus.','Mēneša režģis, detalizēta tabula, laika līnija vai dienu kartītes. Katrā dizainā ir tavs atlasītais mēnesis, maiņu laiki un Kalendārs365 zīmola paraksts.')
   body=body.sub('A4 · 600 ppi','PDF · Attēls · A4')
   if File.file?('downloads/mainas/manifest.json')
    tiles=JSON.parse(File.read('downloads/mainas/manifest.json')).fetch('items').map do |item|
     %(<button class="v2-design-tile" type="button" data-v2-design="#{item['design']}"><span aria-hidden="true"><img src="#{item['preview']}" width="900" height="636" loading="lazy" decoding="async" alt=""></span><strong>#{format('%02d',item['design'])} · #{h(item['title'])}</strong><small>#{h(item['description'])}</small><span class="v2-tile-action">Atvērt priekšskatījumu <b aria-hidden="true">↗</b></span></button>)
    end.join
    body=body.sub('<div class="v2-design-grid" data-v2-design-grid></div>',%(<div class="v2-design-grid" data-v2-design-grid>#{tiles}</div>))
   end
   body+=%(<section class="weekly-print-guide shift-print-guide" aria-labelledby="shift-print-guide-title"><div><span class="eyebrow">SKAIDRS DARBA UN ATPŪTAS RITMS</span><h2 id="shift-print-guide-title">Tavs maiņu mēnesis arī uz papīra</h2></div><div><p>Viena krāsa dienas maiņai, otra nakts maiņai un mierīgs tonis brīvajām dienām palīdz ātri ieraudzīt savu mēnesi. Izvēlies darba ciklu un tā pirmo datumu, pēc tam pārbaudi atlasīto mēnesi. Priekšskatījums izmanto tieši tavu grafiku: mainot mēnesi, ciklu vai individuālu dienas labojumu, izdrukā redzēsi atjaunotos datus. Svētku dienas automātiski nepārraksta maiņu ciklu.</p><p>Izvēlies no 15 oriģināliem noformējumiem. Mēneša režģis rāda maiņu vietu nedēļā; divdaļīgā tabula ļauj salīdzināt sākumu, beigas, neapmaksāto pauzi un plānotās stundas. Laika līnijā redzams darba intervāls diennakts skalā, arī iepriekšējā datumā sāktas nakts maiņas turpinājums. Dienu kartītes dod katram datumam skaidri nodalītu vietu. Apzīmējums <strong>+1</strong> nozīmē beigas nākamajā dienā, bet maiņa tiek pieskaitīta sākuma datumam.</p><p>Saglabā <strong>PDF</strong> ar asu vektoru tekstu vai <strong>Attēls</strong> failu 7016 × 4961 pikseļu izmērā, kas atbilst 600 ppi A4 horizontālai lapai. Katras lapas apakšā ir Kalendārs365 zīmola paraksts un kalendars365.lv adrese. Piezīmes nepazūd: tās un maiņas pāri mēneša robežai turpinās pielikumā; vairāku lapu attēlus saņemsi ZIP failā. Grafika pārcelšanai saglabā JSON dublējumu, bet notikumu importam izmanto ICS. Savu darba laika uzskaiti salīdzini ar darba devēja grafiku; atpūtai noder arī <a href="/atvalinajuma-planotajs/">atvaļinājuma plānotājs</a> un <a href="/darba-dienu-kalendars/">darba dienu kalendārs</a>.</p></div></section>)
  end
 end
 body+=guide if guide
 faq=CATEGORY_V2.fetch(slug).fetch(:faq)
 faq_heading=slug=='visi-riki' ? 'Kā izmantot rīku ceļvedi' : 'Atbildes pirms nākamā plāna.'
 faq_description=slug=='visi-riki' ? 'Īsas atbildes par aprēķiniem, grāmatzīmēm un personīgajiem plāniem.' : 'Latvijas datumi, skaidri pieņēmumi un tavas izvēles.'
 body+%(<section class="v2-answers" id="v2-answers"><div><span class="eyebrow">NODER ZINĀT</span><h2>#{h(faq_heading)}</h2><p>#{h(faq_description)}</p></div><div>#{faq.map{|q,answer|"<details><summary>#{h(q)}<span aria-hidden=\"true\">+</span></summary><p>#{h(answer)}</p></details>"}.join}</div></section>)
end
